 1  import { act, fireEvent, screen } from '@testing-library/react';
 2  import { renderScreen } from '../../test-utils';
 3  import { AccountDialog } from '../AccountDialog';
 4  
 5  function clickOutsideDialog() {
 6    // The dialog's container covers the backdrop; a click on it is a backdrop click.
 7    const container = document.querySelector('.MuiDialog-container');
 8    if (!container) throw new Error('dialog container not found');
 9    fireEvent.mouseDown(container);
10    fireEvent.mouseUp(container);
11    fireEvent.click(container);
12  }
13  
14  describe('AccountDialog', () => {
15    beforeEach(() => jest.useFakeTimers());
16    afterEach(() => jest.useRealTimers());
17  
18    it('deletes only after the confirmation word is typed', () => {
19      const onDelete = jest.fn();
20      renderScreen(<AccountDialog onDelete={onDelete} />);
21      fireEvent.click(screen.getByRole('button', { name: 'Delete account' }));
22  
23      const del = screen.getByRole('button', { name: 'Delete' });
24      expect(del).toBeDisabled();
25      fireEvent.change(screen.getByLabelText('Confirmation'), { target: { value: 'DELETE' } });
26      fireEvent.click(del);
27  
28      expect(onDelete).toHaveBeenCalledTimes(1);
29    });
30  
31    it('stays open, keeping what was typed, when the user clicks outside it', () => {
32      renderScreen(<AccountDialog />);
33      fireEvent.click(screen.getByRole('button', { name: 'Delete account' }));
34      fireEvent.change(screen.getByLabelText('Confirmation'), { target: { value: 'DEL' } });
35  
36      clickOutsideDialog();
37      act(() => {
38        jest.advanceTimersByTime(1000); // longer than any close transition
39      });
40  
41      expect(screen.getByRole('dialog', { name: 'Delete your account?' })).toBeInTheDocument();
42      expect(screen.getByLabelText('Confirmation')).toHaveValue('DEL');
43    });
44  
45    it('closes on Cancel', () => {
46      renderScreen(<AccountDialog />);
47      fireEvent.click(screen.getByRole('button', { name: 'Delete account' }));
48  
49      fireEvent.click(screen.getByRole('button', { name: 'Cancel' }));
50      act(() => {
51        jest.advanceTimersByTime(1000); // longer than any close transition
52      });
53  
54      expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
55    });
56  });
